insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-kiero-refining-enzyme-cleanser', 'Refining Enzyme Cleanser', 'kieró', 'skincare', 'physical', 'A powder face cleanser that turns into a creamy foam with water, made with papaya enzymes (papain), beta-glucan, and chia seed extract. kieró positions it as a gentle daily enzyme exfoliant that removes impurities and excess oil without drying and refines skin texture. It is step 1 of kieró''s 5-step routine, which blends Korean-beauty formulation with Latin American botanicals.', '$11.99 for 50 g (1.76 oz)', '/products/catalog/p-kiero-refining-enzyme-cleanser.webp', 'https://us.kieroskincare.com/products/refining-enzyme-cleanser', '["skin","cleanser","exfoliation","vegan","fragrance-free"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic face cleanser; not an FDA-cleared drug or medical device. kieró states its products are vegan and cruelty-free and use EWG Green-graded ingredients; ayna did not independently verify those claims.","materials":"Water-activated powder (50 g / 1.76 oz). Cleansing comes mainly from mild synthetic surfactants: sodium cocoyl isethionate, sodium methyl cocoyl taurate, and sodium lauroyl glutamate. It also contains potassium laurate, which is a true soap. The enzyme is papain. Supporting ingredients are allantoin, glycerin, beta-glucan, and chia (Salvia hispanica) seed extract. CI 77499 is black iron oxide, a colorant. No added fragrance, essential oils, or sulfates appear in the published ingredient list.","recalls":"No recalls found.","sideEffects":"Papain is a protein-digesting enzyme and a documented allergen. Published cases include workers who became allergic by breathing it in and a person who reacted to papain in a contact-lens solution; one case report also links papain allergy to kiwi and fig allergy. Anyone allergic to papaya, papain, kiwi, or fig should avoid it or patch test first. The AAD warns that exfoliating while using retinoids or benzoyl peroxide can worsen dryness. Full warnings are listed below.","opinionAlerts":"Allergy note: contains papain (papaya enzyme), a known allergen. Avoid it if you''re allergic to papaya, kiwi, or fig, or patch test first. Benefit claims (refined texture, radiance, barrier support) come from kieró, and no independent clinical study of the finished product was found."}'::jsonb, 'kieró says the papaya enzymes gently exfoliate, beta-glucan hydrates and soothes, and chia seed reinforces the skin barrier, and that the powder foams up to remove oil and impurities without drying. No independent study of this product was found, so what follows is what the research says about its main ingredients.

The main cleansing agent, sodium cocoyl isethionate, is the basis of "syndet" (synthetic detergent) cleansers. Reviews describe syndets as gentler on the skin barrier than soap, and lab work explains why: its micelles are too large to slip into the skin''s outer layer. The formula also contains potassium laurate, which is a true soap, so it isn''t entirely soap-free.

Papain breaks down keratin and other skin proteins in lab tests, which is how enzyme exfoliants work. The evidence is thin, though. A review found only 11 published studies on enzyme exfoliation, with few clinical trials, and concluded that more robust studies are needed before it can be recommended as safe. The lab test took hours to break down skin proteins, and a cleanser is rinsed off within a minute, so any exfoliation is likely mild. Papain is also a documented allergen, mostly in workers who breathe it in. In human skin cells and in mice, it weakened the skin barrier and caused sensitization through the skin.

The supporting ingredients have early evidence, all from leave-on products rather than cleansers. For beta-glucan, a 20-patient split-face trial after laser treatment found that a beta-glucan skin-care regimen improved hydration and redness compared with a placebo cream, and an open-label eczema study of 105 patients found less itch and milder flare-ups. For chia seed oil, a 4% chia oil cream improved hydration and barrier function in an 8-week study of just 10 people, with no control group. Allantoin is recognized by the FDA as an over-the-counter skin protectant at 0.5–2%, but kieró doesn''t list its concentration.

The American Academy of Dermatology advises gentle exfoliation for dry or sensitive skin, moisturizing afterward, and not exfoliating while using retinoids or benzoyl peroxide or on broken or sunburned skin.', 'kieró''s US site shows 251 customer reviews, and 233 of them (93%) are five stars. Most reviews are in Spanish and describe skin feeling very clean, soft, and hydrated, for example: "Muy recomendable, te deja la piel suave e hidratada" ("Highly recommend, it leaves your skin soft and hydrated"). On Amazon it has 4.6 out of 5 stars from 36 ratings as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Cleanses with mild syndet surfactants. Papain may add light exfoliation, but enzyme exfoliation has few clinical trials and a cleanser is rinsed off quickly. Evidence for beta-glucan and chia comes from small studies of leave-on products. No independent study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/refining-enzyme-cleanser"},"ingredients":"Full INCI list per kieró: Zea Mays (Corn) Starch, Sodium Cocoyl Isethionate, Microcrystalline Cellulose, Sodium Methyl Cocoyl Taurate, Potassium Laurate, Sodium Lauroyl Glutamate, Allantoin, Maltodextrin, Papain, Water, CI 77499, Glycerin, Salvia Hispanica Seed Extract, 1,2-Hexanediol, Butylene Glycol, Beta-Glucan, Ethylhexylglycerin.","doctorOpinionShort":"A powder cleanser built on syndet surfactants, which are gentler on the skin barrier than soap, with papaya enzyme (papain) for exfoliation. Evidence for enzyme exfoliation is thin, and the beta-glucan and chia research comes from small studies of leave-on products, not rinse-off cleansers. Papain is a documented allergen, so avoid it if you''re allergic to papaya, kiwi, or fig. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","label":"kieroskincare.com: Refining Enzyme Cleanser, ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","label":"American Academy of Dermatology: How to safely exfoliate at home"}],"whoItsFor":["People who want gentle, daily enzyme exfoliation instead of a scrub or acid","Normal, oily, or combination skin looking for a cleanser that removes excess oil without a tight, stripped feeling","People who prefer a fragrance-free, vegan formula"],"howToUse":{"intro":"Per kieró''s own site: use daily as step 1 (cleanse) of the routine.","steps":["Pour a small amount of powder into wet hands.","Rub your hands together to create a creamy lather, then gently massage it into your skin.","Rinse well and pat your face dry.","Follow with moisturizer. The AAD recommends moisturizing right after any exfoliation."],"sourceUrl":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","sourceLabel":"kieroskincare.com: Refining Enzyme Cleanser"},"warnings":["Allergy to papaya, papain, kiwi, or fig: avoid it or patch test first. Papain is a known allergen.","Using a prescription retinoid, retinol, or benzoyl peroxide: exfoliating on top of them can worsen dryness and irritation (AAD).","Don''t use on broken, cut, or sunburned skin.","Keep out of eyes. If you get redness, burning, or an allergic reaction, stop using it and see a doctor."],"ingredientScience":[{"name":"Papain (papaya enzyme)","text":"kieró states this gently exfoliates. In a lab study, papain broke down keratin and collagen, and on pig skin it had an exfoliating effect, though breakdown took hours. A review (J Cosmet Dermatol, 2022) found only 11 studies on enzyme exfoliation, few of them clinical trials. It concluded that more robust studies are needed before enzyme exfoliation can be recommended as safe. Papain is also an allergen. In human skin cells and in mice it weakened the skin barrier and caused sensitization through the skin. In people, papain allergy is mostly documented in workers who breathe it in, and one case report links it to kiwi and fig allergy.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34897928/","label":"PubMed: An overview of the use of proteolytic enzymes as exfoliating agents"},{"url":"https://pubmed.ncbi.nlm.nih.gov/35892222/","label":"PubMed: In vitro effect on the proteolytic activity of papain with proteins of the skin as substrate"},{"url":"https://pubmed.ncbi.nlm.nih.gov/25705851/","label":"PubMed: Papain degrades tight junction proteins of human keratinocytes in vitro and sensitizes mice via the skin"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26739411/","label":"PubMed: Papain-induced occupational asthma with kiwi and fig allergy, case report and review of 13 cases"}]},{"name":"Beta-glucan","text":"kieró states this hydrates and soothes. In a split-face, double-blind trial of 20 patients after laser treatment, a beta-glucan skin-care regimen improved hydration and redness compared with a placebo cream. In an open-label study (no blinding or separate control group) of 105 people with mild-to-moderate eczema, a beta-glucan cream reduced itch and eczema severity on the treated side. Both tested leave-on products, not a rinse-off cleanser.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33128496/","label":"PubMed: Skin care regimens containing β-glucan for skin recovery after fractional laser therapy, split-face, double-blinded, vehicle-controlled study"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26654776/","label":"PubMed: β-Glucan-based cream in supportive treatment of mild-to-moderate atopic dermatitis"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12023766/","label":"NIH (PMC): Exploring the properties and application potential of β-glucan in skin care"}]},{"name":"Chia seed (Salvia hispanica) extract","text":"kieró states this reinforces the skin barrier. In an 8-week study of 10 people with dry, itchy skin and no control group, a cream with 4% chia seed oil improved skin hydration and barrier function, with no side effects reported. The study was run by a company that makes skin products, and it tested a leave-on oil, not a rinse-off extract.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20548903/","label":"PubMed: Effectiveness of topical chia seed oil on pruritus of end-stage renal disease patients and healthy volunteers"}]},{"name":"Sodium cocoyl isethionate","text":"The main cleansing agent. Lab research found its micelles are too large to get into the skin''s outer layer, which explains why it is milder than soap or sodium lauryl sulfate. A 2022 review concludes that syndet cleansers like this preserve the skin barrier better than soap.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17598025/","label":"PubMed: Why is sodium cocoyl isethionate (SCI) mild to the skin barrier?"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8954092/","label":"NIH (PMC): Skin cleansing without or with compromise, soaps and syndets"}]},{"name":"Allantoin","text":"The FDA recognizes allantoin as an over-the-counter skin-protectant ingredient at 0.5–2%. kieró doesn''t list how much this cleanser contains, and in a rinse-off product little stays on the skin.","citations":[{"url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-347/subpart-B/section-347.10","label":"FDA (21 CFR 347.10): Skin protectant active ingredients, allantoin, 0.5 to 2 percent"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","text":"American Academy of Dermatology: How to safely exfoliate at home","summary":"AAD guidance: people with dry, sensitive, or acne-prone skin should choose gentle exfoliation, moisturize afterward, and avoid exfoliating on broken or sunburned skin or while using retinoids or benzoyl peroxide. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FRMDSSY6","text":"Amazon: kieró Refining Enzyme Cleanser reviews","summary":"4.6 out of 5 stars from 36 ratings on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","text":"kieroskincare.com: Refining Enzyme Cleanser customer reviews","summary":"kieró''s own product page shows 251 reviews, 93% of them five stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-airy-sun-stick-spf50', 'Airy Sun Stick SPF 50+', 'kieró', 'skincare', 'physical', 'A broad-spectrum SPF 50+ / PA++++ sunscreen stick with chamomile, vitamin E, and madecassoside (from centella). kieró positions it for daily UV protection with a lightweight, non-greasy finish that can be swiped on over makeup, and says it soothes and supports the skin barrier. It uses chemical (organic) UV filters, not zinc or titanium.', '$11.99 for 20 g (0.7 oz)', '/products/catalog/p-kiero-airy-sun-stick-spf50.webp', 'https://us.kieroskincare.com/products/sun-stick-spf-50', '["skin","spf","sunscreen","vegan"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"In the US, sunscreens are regulated as over-the-counter drugs. kieró doesn''t publish the percentage of each UV filter or say whether the product is water resistant. kieró states its products are vegan and cruelty-free; ayna did not independently verify that.","materials":"Solid silicone-and-wax stick (20 g / 0.7 oz). UV filters: avobenzone (UVA), octocrylene, homosalate, octisalate, and butyloctyl salicylate, all chemical filters with no zinc oxide or titanium dioxide. The soothing ingredients are Roman chamomile flower water, sodium guaiazulene sulfonate (an azulene compound related to chamomile''s blue oil), madecassoside with other centella compounds, panthenol, and vitamin E. Plant oils include sunflower, avocado, soybean, shea, and annatto (Bixa orellana).","recalls":"No recalls found.","sideEffects":"Octocrylene can cause photoallergic reactions (a rash after sun exposure), notably in people who have reacted to ketoprofen, an anti-inflammatory gel. The formula contains Roman chamomile, a daisy-family (Asteraceae) plant; this family is a known contact allergen and cross-reacts with ragweed, so people with those allergies should patch test first. Full warnings are listed below.","opinionAlerts":"Safety note: sunscreen only reaches its labeled SPF when applied generously, and most people apply far less, so go over each area several times. Its chemical UV filters were absorbed into the bloodstream in an FDA study; the FDA researchers said that doesn''t mean people should stop using sunscreen. Contains Roman chamomile, so patch test if you''re allergic to ragweed or daisies. Soothing and barrier claims come from kieró, and no independent study of the finished product was found."}'::jsonb, 'kieró says the chamomile soothes, the vitamin E gives antioxidant defense, and the madecassoside strengthens the skin barrier, and that the stick can be swiped on over makeup. No independent study of this product was found, so what follows is what the research says about daily sunscreen and its ingredients.

The strongest evidence is for daily sunscreen use itself, from a randomized trial of 1,621 adults in Nambour, Australia, using an SPF 15+ sunscreen. People assigned to daily use had 24% less skin aging over 4.5 years than people who used sunscreen when they chose to. They also had about 39% fewer squamous cell carcinoma tumors, though the share of people who got one didn''t differ significantly, and there was no effect on basal cell carcinoma. Ten years later, the daily group had 11 new melanomas versus 22, a difference just short of statistical significance overall, though the drop in invasive melanoma (3 vs 11) was significant.

How much you apply matters. SPF is tested at 2 mg/cm², while consumers typically apply 0.5–1 mg/cm², and lab studies show actual SPF drops steeply at those amounts. One study found SPF 30–50 products may not give enough protection at typical consumer amounts. The AAD and FDA advise applying 15 minutes before sun exposure and reapplying at least every two hours, and more often when swimming or sweating. kieró doesn''t claim water resistance.

The UV filters in this stick (avobenzone, octocrylene, homosalate, octisalate) were all absorbed into the bloodstream in a 2020 FDA randomized trial of 48 people. Levels were above the point at which the FDA can waive further safety testing, and the FDA researchers said this does not mean people should stop using sunscreen. A separate lab study found benzophenone, which it calls a possible human carcinogen, in all 28 octocrylene-containing products tested, increasing with age and heat. People who want to avoid these filters can choose a mineral (zinc oxide) sunscreen.

For the soothing ingredients, a 6-month double-blind study of 20 women found that a cream combining 5% vitamin C with 0.1% madecassoside improved wrinkles, firmness, and hydration. Because the two were combined, the result can''t be credited to madecassoside alone. In a separate study, madecassoside reduced UV-triggered inflammation in skin cells and reduced UV tanning on human skin over 8 weeks. Vitamin E is the main antioxidant naturally found in skin.', 'kieró''s US site shows 657 customer reviews, and 593 of them (90%) are five stars; the rest are four stars. Most reviews are in Spanish and praise how easily it goes on, how fast it absorbs, and its non-greasy feel, including over makeup. For example: "No es grasoso y protege muy bien tu piel del sol" ("It''s not greasy and protects your skin from the sun really well"). On Amazon it has 4.5 out of 5 stars from 28 ratings (69% five-star, 26% four-star, 5% one-star) as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Labeled SPF 50+ / PA++++ broad spectrum, but real-world protection depends on how much you apply. Daily sunscreen use slowed skin aging and reduced squamous cell carcinoma tumors in a randomized trial. No independent study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/sun-stick-spf-50"},"ingredients":"Full INCI list per kieró: Dimethicone, Synthetic Wax, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Cetyl Ethylhexanoate, Octocrylene, Homosalate, Methyl Methacrylate Crosspolymer, Dibutyl Adipate, Butyloctyl Salicylate, Octisalate, Avobenzone, Pentylene Glycol, Polyglyceryl-4 Oleate, Helianthus Annuus (Sunflower) Seed Oil, Polyglyceryl-6 Oleate, Polyhydroxystearic Acid, Methylpropanediol, Persea Gratissima (Avocado) Oil, Ethylhexylglycerin, Caprylyl Glycol, Glycine Soja (Soybean) Oil, Tocopherol, Steareth-30, Lactobacillus Ferment Lysate, Butyrospermum Parkii (Shea) Butter Extract, Bixa Orellana Seed Oil, Water, Sodium Guaiazulene Sulfonate, Panthenol, Butylene Glycol, 1,2-Hexanediol, Anthemis Nobilis Flower Water, Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid.","doctorOpinionShort":"Daily sunscreen use slowed skin aging and reduced squamous cell carcinoma tumors in a large randomized trial, with a likely drop in invasive melanoma. Protection depends on applying enough, so go over each area several times and reapply every two hours. Its chemical filters are absorbed into the blood; the FDA researchers said that doesn''t mean people should stop using sunscreen, and mineral sunscreen is an alternative. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/sun-stick-spf-50","label":"kieroskincare.com: Airy Sun Stick SPF 50+, ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","label":"American Academy of Dermatology: How to apply sunscreen"},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","label":"FDA: Sunscreen, how to help protect your skin from the sun"},{"url":"https://pubmed.ncbi.nlm.nih.gov/10475183/","label":"PubMed: Daily sunscreen application in prevention of basal-cell and squamous-cell carcinomas, randomised controlled trial","chipLabel":"Nambour sunscreen trial (Lancet 1999)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","label":"PubMed: Sunscreen and prevention of skin aging, a randomized trial (Ann Intern Med 2013)","chipLabel":"Sunscreen and skin aging trial (2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/21135266/","label":"PubMed: Reduced melanoma after regular sunscreen use, randomized trial follow-up (J Clin Oncol 2011)","chipLabel":"Sunscreen and melanoma follow-up (2011)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/19614894/","label":"PubMed: The influence of the amount of sunscreen applied on its sun protection factor","chipLabel":"Sunscreen amount and SPF study"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31961417/","label":"PubMed: Effect of sunscreen application on plasma concentration of sunscreen active ingredients, randomized clinical trial (JAMA 2020)","chipLabel":"FDA sunscreen absorption trial (JAMA 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33763894/","label":"PubMed: The presence of benzophenone in sunscreens and cosmetics containing the organic UV filter octocrylene","chipLabel":"Benzophenone in octocrylene products (2021)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin","chipLabel":"Vitamin C + madecassoside trial, 20 women"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6290557/","label":"NIH (PMC): Madecassoside inhibits melanin synthesis by blocking ultraviolet-induced inflammation","chipLabel":"Madecassoside UV study"},{"url":"https://pubmed.ncbi.nlm.nih.gov/12239421/","label":"PubMed: Antioxidants and the response of skin to oxidative stress, vitamin E as a key indicator","chipLabel":"Vitamin E in skin (review)"}],"whoItsFor":["People who want a mess-free daily SPF they can reapply over makeup","Oily or combination skin looking for a non-greasy finish","Touch-ups on the face, ears, nose, and around the eyes during the day"],"howToUse":{"intro":"Per kieró''s own site: swipe the stick on as the last step of your morning routine, or over makeup, evenly covering all sun-exposed areas. Reapply through the day as needed.","steps":["Go over each area several times (back and forth). A single light swipe won''t deliver the labeled SPF.","Apply about 15 minutes before going outside (AAD).","Reapply at least every two hours, and right after swimming or sweating (AAD / FDA)."],"sourceUrl":"https://us.kieroskincare.com/products/sun-stick-spf-50","sourceLabel":"kieroskincare.com: Airy Sun Stick SPF 50+"},"warnings":["Allergy to ragweed, chamomile, or other daisy-family plants: patch test first.","Have you reacted to ketoprofen (an anti-inflammatory gel)? Octocrylene can cause photoallergic reactions in people sensitized to it.","Rash or irritation, especially after sun exposure: stop using it and see a doctor.","Not stated as water resistant: reapply after swimming or sweating.","Infants under 6 months: the FDA doesn''t recommend sunscreen; keep them out of the sun instead."],"ingredientScience":[{"name":"Daily broad-spectrum sunscreen","text":"In the Nambour randomized trial (1,621 adults, SPF 15+), people assigned to daily sunscreen showed no detectable increase in skin aging over 4.5 years, 24% less aging than the discretionary-use group. They had 39% fewer squamous cell carcinoma tumors, though the share of people who got one didn''t differ significantly, and there was no effect on basal cell carcinoma. Ten years later, the daily group had 11 new melanomas vs 22; that overall difference was just short of statistical significance (p = 0.051), while the drop in invasive melanoma (3 vs 11) was significant.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10475183/","label":"PubMed: Daily sunscreen application in prevention of basal-cell and squamous-cell carcinomas, a randomised controlled trial (Green et al., Lancet 1999)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","label":"PubMed: Sunscreen and prevention of skin aging, a randomized trial (Hughes et al., Ann Intern Med 2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/21135266/","label":"PubMed: Reduced melanoma after regular sunscreen use, randomized trial follow-up (Green et al., J Clin Oncol 2011)"}]},{"name":"How much you apply","text":"SPF is measured at 2 mg/cm², but consumers typically apply 0.5–1 mg/cm². Lab studies on volunteers found actual SPF falls significantly at lower amounts. One found SPF 30–50 products may not give enough protection at typical consumer amounts.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19614894/","label":"PubMed: The influence of the amount of sunscreen applied on its sun protection factor"},{"url":"https://pubmed.ncbi.nlm.nih.gov/22463921/","label":"PubMed: High-SPF sunscreens may compensate for lower user application amounts"}]},{"name":"Chemical UV filters (avobenzone, octocrylene, homosalate, octisalate)","text":"In a 2020 FDA randomized trial of 48 people, all of these filters were absorbed into the bloodstream after a single application, above the level at which the FDA can waive further safety testing. The researchers concluded this does not mean people should stop using sunscreen. A separate lab study found benzophenone, a possible human carcinogen, in all 28 octocrylene-containing products tested. Levels rose with time and heat.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31961417/","label":"PubMed: Effect of sunscreen application on plasma concentration of sunscreen active ingredients, a randomized clinical trial (JAMA 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33763894/","label":"PubMed: The presence of benzophenone in sunscreens and cosmetics containing the organic UV filter octocrylene"}]},{"name":"Madecassoside (centella)","text":"kieró states this strengthens the skin barrier. No study testing madecassoside alone for barrier strength was found. In a 6-month double-blind study of 20 women, a cream combining 5% vitamin C with 0.1% madecassoside improved wrinkles, firmness, and hydration, but the result can''t be credited to madecassoside alone. In another study, madecassoside reduced UV-triggered inflammation in skin cells and reduced UV tanning on human skin over 8 weeks.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6290557/","label":"NIH (PMC): Madecassoside inhibits melanin synthesis by blocking ultraviolet-induced inflammation"}]},{"name":"Roman chamomile","text":"kieró states this soothes sensitive skin. No study of chamomile flower water for soothing was found. Chamomile is in the daisy (Asteraceae) family, whose compounds are known skin sensitizers that can cross-react with ragweed.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11847717/","label":"NIH (PMC): Allergic potential of medicinal plants from the Asteraceae family (2025 review)"}]},{"name":"Vitamin E","text":"kieró states this gives antioxidant defense. Vitamin E is the main antioxidant naturally found in human skin, and UV exposure depletes it.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12239421/","label":"PubMed: Antioxidants and the Response of Skin to Oxidative Stress, Vitamin E as a Key Indicator"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","text":"American Academy of Dermatology: How to apply sunscreen","summary":"AAD guidance: use SPF 30+ broad-spectrum sunscreen, apply about 15 minutes before going out, and reapply every two hours and after swimming or sweating. This is general guidance, not product-specific validation."},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","text":"FDA: Sunscreen, how to help protect your skin from the sun","summary":"FDA guidance: use broad-spectrum SPF 15+, apply 15 minutes before sun exposure, reapply at least every two hours, and keep infants under 6 months out of the sun rather than using sunscreen."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0HBVSP2QH","text":"Amazon: kieró Airy Sun Stick reviews","summary":"4.5 out of 5 stars from 28 ratings (69% five-star, 26% four-star, 5% one-star) on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/sun-stick-spf-50","text":"kieroskincare.com: Airy Sun Stick SPF 50+ customer reviews","summary":"kieró''s own product page shows 657 reviews, 90% of them five stars and the rest four stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-comfort-cleansing-balm', 'Comfort Cleansing Balm', 'kieró', 'skincare', 'physical', 'A cleansing balm with grape seed oil, macadamia oil and vitamin E that melts on contact to dissolve makeup and impurities. kieró positions it as a first cleanse that removes makeup without drying and protects the skin''s moisture barrier. Massage it onto dry skin, then rinse with warm water. It is step 1 (cleanse) of kieró''s 5-step routine.', '$11.99 for 80 g (2.82 oz)', '/products/catalog/p-kiero-comfort-cleansing-balm.webp', 'https://us.kieroskincare.com/products/comfort-cleansing-balm', '["skin","cleanser","cleansing balm","makeup remover","oil cleanser","vegan","fragrance-free"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic cleanser; not an FDA-cleared drug or medical device. kieró states its products are vegan and cruelty-free; ayna did not independently verify that.","materials":"Solid balm (80 g / 2.82 oz) made mostly of emollient esters, oils and wax, with grape seed, moringa, jojoba, macadamia and sunflower oils, vitamin E (tocopherol), and small amounts of plant extracts including neem (Melia azadirachta), turmeric, holy basil (Ocimum sanctum) and eggplant. No water, added fragrance or essential oils appear in the published ingredient list.","recalls":"No recalls found.","sideEffects":"None reported by kieró. It contains several plant extracts and macadamia seed oil, so patch test first if you have sensitive skin or plant or nut allergies. Full warnings are listed below.","opinionAlerts":"Claims that it soothes sensitive skin and strengthens the skin barrier come from kieró, and no independent study of the finished product was found. One reviewer noted it doesn''t melt as quickly as expected."}'::jsonb, 'kieró says the balm dissolves makeup and impurities without drying, soothes and protects sensitive skin, and nourishes the skin barrier, crediting grape seed oil, macadamia oil and vitamin E.

No independent study of this product, or of cleansing balms as a category, was found, so these benefits rest on kieró''s own claims. Vitamin E is the main antioxidant naturally found in skin, but in a rinse-off cleanser most of it is washed away. The formula lists no added fragrance or essential oils.', 'kieró''s US site shows 334 customer reviews, and 311 of them (93%) are five stars; the rest are four stars. Most reviews are in Spanish and praise how fully it removes makeup, including waterproof makeup and long-wear lipstick, and that it has no scent. For example: "Me encantó que removió todo el maquillaje de mi rostro" ("I loved that it removed all the makeup from my face"). One reviewer said it doesn''t melt as quickly as expected. On Amazon it has 4.5 out of 5 stars from 58 ratings as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Reviewers on kieró''s site say it removes even waterproof makeup and long-wear lipstick without scrubbing.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/comfort-cleansing-balm"},"ingredients":"Full INCI list per kieró: Cetyl Ethylhexanoate, Caprylic/Capric Triglyceride, PEG-20 Glyceryl Triisostearate, PEG-10 Isostearate, Synthetic Wax, Sorbitan Sesquioleate, Glyceryl Caprylate, Ethylhexylglycerin, Vitis Vinifera (Grape) Seed Oil, Eclipta Prostrata Extract, Melia Azadirachta Leaf Extract, Melia Azadirachta Flower Extract, Coccinia Indica Fruit Extract, Solanum Melongena (Eggplant) Fruit Extract, Moringa Oleifera Seed Oil, Simmondsia Chinensis (Jojoba) Seed Oil, Corallina Officinalis Extract, Curcuma Longa (Turmeric) Root Extract, Ocimum Sanctum Leaf Extract, Macadamia Ternifolia Seed Oil, Tocopherol, Helianthus Annuus (Sunflower) Seed Oil, Vegetable Oil.","doctorOpinionShort":"An oil-based makeup-removing balm with no added fragrance. Its soothing and barrier claims come from kieró, and no independent study of the product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/comfort-cleansing-balm","label":"kieroskincare.com: Comfort Cleansing Balm, ingredient list and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/12239421/","label":"PubMed: Antioxidants and the response of skin to oxidative stress, vitamin E as a key indicator","chipLabel":"Vitamin E in skin (review)"}],"whoItsFor":["People who wear makeup or sunscreen and want a first cleanse that dissolves it without scrubbing","Dry or normal skin that feels tight after foaming cleansers","People who prefer a fragrance-free, vegan formula"],"howToUse":{"intro":"Per kieró''s own site: use as step 1 (cleanse) of the routine.","steps":["Scoop a small amount onto dry hands.","Massage it onto a dry face in circular motions to dissolve makeup.","Rinse with warm water."],"sourceUrl":"https://us.kieroskincare.com/products/comfort-cleansing-balm","sourceLabel":"kieroskincare.com: Comfort Cleansing Balm"},"warnings":["Plant or nut allergies (it contains macadamia oil and several plant extracts): patch test first.","Keep out of eyes. If you get redness, burning, or a rash, stop using it."],"ingredientScience":[{"name":"Vitamin E","text":"kieró credits vitamin E for nourishing the skin. Vitamin E is the main antioxidant naturally found in human skin, and UV exposure depletes it. In a rinse-off cleanser, most of it is washed away.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12239421/","label":"PubMed: Antioxidants and the Response of Skin to Oxidative Stress, Vitamin E as a Key Indicator"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FRMXWM2M","text":"Amazon: kieró Comfort Cleansing Balm reviews","summary":"4.5 out of 5 stars from 58 ratings on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/comfort-cleansing-balm","text":"kieroskincare.com: Comfort Cleansing Balm customer reviews","summary":"kieró''s own product page shows 334 reviews, 93% of them five stars and the rest four stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-prime-sun-gel-spf40', 'Prime Sun Gel SPF 40+', 'kieró', 'skincare', 'physical', 'A lightweight gel sunscreen labeled SPF 40+ / PA++++ broad spectrum, with chamomile, azulene and panthenol. kieró positions it for daily UV protection in a fast-absorbing, non-sticky texture that soothes sensitive skin and redness, hydrates, and wears alone or under makeup. It is the last step (protect) of kieró''s morning routine.', '$12.99 for 50 ml (1.69 fl oz)', '/products/catalog/p-kiero-prime-sun-gel-spf40.webp', 'https://us.kieroskincare.com/products/sun-barrier', '["skin","spf","sunscreen","vegan"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"In the US, sunscreens are regulated as over-the-counter drugs. No FDA drug listing for this product was found in openFDA''s NDC directory (checked 2026-10-06), so the SPF 40+ / PA++++ and broad-spectrum claims are per kieró. kieró doesn''t publish the percentage of each UV filter or say whether it is water resistant. kieró states the formula is vegan and free of sulfates, parabens and phthalates; ayna did not independently verify that.","materials":"Silicone-based gel (50 ml / 1.69 fl oz). UV filters: avobenzone (UVA), octocrylene, homosalate, octisalate, and butyloctyl salicylate, all chemical filters with no zinc oxide or titanium dioxide. Soothing ingredients are Roman chamomile flower water, sodium guaiazulene sulfonate (an azulene derivative), panthenol, and madecassoside (from centella). It also contains soybean oil, vitamin E, and added fragrance.","recalls":"No recalls found.","sideEffects":"Octocrylene can cause photoallergic reactions (a rash after sun exposure), notably in people who have reacted to ketoprofen, an anti-inflammatory gel. The formula contains Roman chamomile, a daisy-family (Asteraceae) plant; this family is a known contact allergen and cross-reacts with ragweed. It also contains added fragrance. People with those allergies or fragrance sensitivity should patch test first. Full warnings are listed below.","opinionAlerts":"Safety note: sunscreen only reaches its labeled SPF when applied generously, and most people apply far less. Its chemical UV filters were absorbed into the bloodstream in an FDA study; the FDA researchers said that doesn''t mean people should stop using sunscreen. Contains added fragrance and Roman chamomile, so patch test if you''re fragrance-sensitive or allergic to ragweed or daisies. No FDA drug listing for this product was found. Soothing and redness claims come from kieró, and no independent study of the finished product was found."}'::jsonb, 'kieró says chamomile and azulene soothe sensitive skin and reduce redness, panthenol hydrates and strengthens the barrier, and the gel wears well alone or under makeup. No independent study of this product was found, and no FDA drug listing for it was found, so its SPF rating is per kieró.

The strongest evidence is for daily sunscreen use itself, from a randomized trial of 1,621 adults in Nambour, Australia, using an SPF 15+ sunscreen. People assigned to daily use had 24% less skin aging over 4.5 years than people who used sunscreen when they chose to. They also had about 39% fewer squamous cell carcinoma tumors, though the share of people who got one didn''t differ significantly, and there was no effect on basal cell carcinoma. Ten years later, the daily group had 11 new melanomas versus 22, a difference just short of statistical significance overall, though the drop in invasive melanoma (3 vs 11) was significant.

How much you apply matters. SPF is tested at 2 mg/cm², while consumers typically apply 0.5–1 mg/cm², and lab studies show actual SPF drops steeply at those amounts. The AAD and FDA advise applying 15 minutes before sun exposure and reapplying at least every two hours, and more often when swimming or sweating. kieró doesn''t claim water resistance.

The UV filters in this gel (avobenzone, octocrylene, homosalate, octisalate) were all absorbed into the bloodstream in a 2020 FDA randomized trial of 48 people, above the point at which the FDA can waive further safety testing; the FDA researchers said this does not mean people should stop using sunscreen. People who want to avoid these filters can choose a mineral (zinc oxide) sunscreen.

For the soothing ingredients: panthenol''s active form, dexpanthenol, improved skin hydration and reduced water loss through the skin within 7 days in a small randomized, double-blind, placebo-controlled study. No human study of sodium guaiazulene sulfonate for redness was found; a 2003 lab study in bacteria found azulene and guaiazulene became mutagenic when exposed to UVA or visible light, which has not been tested in people. The gel also contains added fragrance, which can irritate sensitive skin.', 'kieró''s US site shows 310 customer reviews, and 287 of them (93%) are five stars; 22 are four stars and one is one star. Most reviews are in Spanish and praise the light texture, fast absorption, and hydrated feel. For example: "Textura ligera y se siente muy bien en la piel" ("Light texture and it feels great on the skin"). On Amazon it has 4.5 out of 5 stars from 34 ratings (75% five-star; 5% two-star, none one-star) as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Daily sunscreen use slowed skin aging and reduced squamous cell carcinoma tumors in a large randomized trial.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/sun-barrier"},"ingredients":"Full INCI list per kieró: Isododecane, Cyclopentasiloxane, Homosalate, Octocrylene, Cyclohexasiloxane, Dimethicone/Bis-Isobutyl PPG-20 Crosspolymer, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Octisalate, Butyloctyl Salicylate, Avobenzone, 1,2-Hexanediol, Helianthus Annuus (Sunflower) Seed Oil, Polyglyceryl-4 Oleate, Water, C12-13 Pareth-9, Polyglyceryl-6 Oleate, Polyhydroxystearic Acid, Ethylhexylglycerin, Glycine Soja (Soybean) Oil, Caryodendron Orinocense Seed Oil, Tocopherol, Plukenetia Volubilis Seed Oil, Bixa Orellana Seed Oil, Sodium Guaiazulene Sulfonate, Panthenol, Butylene Glycol, Anthemis Nobilis Flower Water, Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid, Fragrance.","doctorOpinionShort":"Daily sunscreen use slowed skin aging and reduced squamous cell carcinoma tumors in a large randomized trial. Protection depends on applying enough and reapplying every two hours. No FDA drug listing for this product was found, so its SPF 40+ rating is per kieró. It contains added fragrance and chemical filters that are absorbed into the blood; mineral sunscreen is an alternative.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/sun-barrier","label":"kieroskincare.com: Prime Sun Gel SPF 40+, ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","label":"American Academy of Dermatology: How to apply sunscreen"},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","label":"FDA: Sunscreen, how to help protect your skin from the sun"},{"url":"https://pubmed.ncbi.nlm.nih.gov/10475183/","label":"PubMed: Daily sunscreen application in prevention of basal-cell and squamous-cell carcinomas, randomised controlled trial","chipLabel":"Nambour sunscreen trial (Lancet 1999)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","label":"PubMed: Sunscreen and prevention of skin aging, a randomized trial (Ann Intern Med 2013)","chipLabel":"Sunscreen and skin aging trial (2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/21135266/","label":"PubMed: Reduced melanoma after regular sunscreen use, randomized trial follow-up (J Clin Oncol 2011)","chipLabel":"Sunscreen and melanoma follow-up (2011)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/19614894/","label":"PubMed: The influence of the amount of sunscreen applied on its sun protection factor","chipLabel":"Sunscreen amount and SPF study"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31961417/","label":"PubMed: Effect of sunscreen application on plasma concentration of sunscreen active ingredients, randomized clinical trial (JAMA 2020)","chipLabel":"FDA sunscreen absorption trial (JAMA 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/10965426/","label":"PubMed: Effect of topically applied dexpanthenol on epidermal barrier function and stratum corneum hydration","chipLabel":"Dexpanthenol skin barrier trial (2000)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3767376/","label":"NIH (PMC): Photomutagenicity of cosmetic ingredient chemicals azulene and guaiazulene","chipLabel":"Azulene lab study (2003)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin","chipLabel":"Vitamin C + madecassoside trial, 20 women"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6290557/","label":"NIH (PMC): Madecassoside inhibits melanin synthesis by blocking ultraviolet-induced inflammation","chipLabel":"Madecassoside UV study"}],"whoItsFor":["People who want a lightweight daily sunscreen that works under makeup","Oily or combination skin looking for a non-sticky gel finish","Not ideal for fragrance-sensitive skin, since it contains added fragrance"],"howToUse":{"intro":"Per kieró''s own site: use alone or as the last step of your morning routine, before makeup.","steps":["Apply evenly to all sun-exposed skin. Use enough: most people apply far less than the amount SPF is tested at.","Apply about 15 minutes before going outside (AAD).","Reapply at least every two hours, and right after swimming or sweating (AAD / FDA)."],"sourceUrl":"https://us.kieroskincare.com/products/sun-barrier","sourceLabel":"kieroskincare.com: Prime Sun Gel SPF 40+"},"warnings":["Contains added fragrance: patch test if you have fragrance-sensitive skin.","Allergy to ragweed, chamomile, or other daisy-family plants: patch test first.","Have you reacted to ketoprofen (an anti-inflammatory gel)? Octocrylene can cause photoallergic reactions in people sensitized to it.","Not stated as water resistant: reapply after swimming or sweating.","Infants under 6 months: the FDA doesn''t recommend sunscreen; keep them out of the sun instead."],"ingredientScience":[{"name":"Daily broad-spectrum sunscreen","text":"In the Nambour randomized trial (1,621 adults, SPF 15+), people assigned to daily sunscreen showed no detectable increase in skin aging over 4.5 years, 24% less aging than the discretionary-use group. They had 39% fewer squamous cell carcinoma tumors, though the share of people who got one didn''t differ significantly, and there was no effect on basal cell carcinoma. Ten years later, the daily group had 11 new melanomas vs 22; that overall difference was just short of statistical significance (p = 0.051), while the drop in invasive melanoma (3 vs 11) was significant.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10475183/","label":"PubMed: Daily sunscreen application in prevention of basal-cell and squamous-cell carcinomas, a randomised controlled trial (Green et al., Lancet 1999)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","label":"PubMed: Sunscreen and prevention of skin aging, a randomized trial (Hughes et al., Ann Intern Med 2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/21135266/","label":"PubMed: Reduced melanoma after regular sunscreen use, randomized trial follow-up (Green et al., J Clin Oncol 2011)"}]},{"name":"How much you apply","text":"SPF is measured at 2 mg/cm², but consumers typically apply 0.5–1 mg/cm². Lab studies on volunteers found actual SPF falls significantly at lower amounts. One found SPF 30–50 products may not give enough protection at typical consumer amounts.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19614894/","label":"PubMed: The influence of the amount of sunscreen applied on its sun protection factor"},{"url":"https://pubmed.ncbi.nlm.nih.gov/22463921/","label":"PubMed: High-SPF sunscreens may compensate for lower user application amounts"}]},{"name":"Chemical UV filters (avobenzone, octocrylene, homosalate, octisalate)","text":"In a 2020 FDA randomized trial of 48 people, all of these filters were absorbed into the bloodstream after a single application, above the level at which the FDA can waive further safety testing. The researchers concluded this does not mean people should stop using sunscreen. A separate lab study found benzophenone, a possible human carcinogen, in all 28 octocrylene-containing products tested. Levels rose with time and heat.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31961417/","label":"PubMed: Effect of sunscreen application on plasma concentration of sunscreen active ingredients, a randomized clinical trial (JAMA 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33763894/","label":"PubMed: The presence of benzophenone in sunscreens and cosmetics containing the organic UV filter octocrylene"}]},{"name":"Panthenol","text":"kieró states this hydrates and strengthens the skin barrier. In a small randomized, double-blind, placebo-controlled study, dexpanthenol (panthenol''s active form) in two lipophilic creams improved skin hydration and reduced water loss through the skin after 7 days compared with the same creams without it. A 2017 review describes dexpanthenol''s use as a moisturizer and barrier restorer; three of its four authors work for Bayer Consumer Care.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10965426/","label":"PubMed: Effect of topically applied dexpanthenol on epidermal barrier function and stratum corneum hydration (Gehring & Gloor, 2000)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28503966/","label":"PubMed: Topical use of dexpanthenol, a 70th anniversary article (Proksch et al., 2017)"}]},{"name":"Azulene (sodium guaiazulene sulfonate)","text":"kieró states azulene reduces redness. No human study of sodium guaiazulene sulfonate for redness was found. A 2003 lab study in bacteria found azulene and guaiazulene became mutagenic when exposed to UVA or visible light, though not in the dark. That was not a study in people or skin, it tested guaiazulene rather than the sulfonate form used here, and its relevance to sunscreen use is unknown.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3767376/","label":"NIH (PMC): Photomutagenicity of cosmetic ingredient chemicals azulene and guaiazulene (2003)"}]},{"name":"Madecassoside (centella)","text":"No study testing madecassoside alone for barrier strength was found. In a 6-month double-blind study of 20 women, a cream combining 5% vitamin C with 0.1% madecassoside improved wrinkles, firmness, and hydration, but the result can''t be credited to madecassoside alone. In another study, madecassoside reduced UV-triggered inflammation in skin cells and reduced UV tanning on human skin over 8 weeks.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6290557/","label":"NIH (PMC): Madecassoside inhibits melanin synthesis by blocking ultraviolet-induced inflammation"}]},{"name":"Roman chamomile","text":"kieró states this soothes sensitive skin. No study of chamomile flower water for soothing was found. Chamomile is in the daisy (Asteraceae) family, whose compounds are known skin sensitizers that can cross-react with ragweed.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11847717/","label":"NIH (PMC): Allergic potential of medicinal plants from the Asteraceae family (2025 review)"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","text":"American Academy of Dermatology: How to apply sunscreen","summary":"AAD guidance: use SPF 30+ broad-spectrum sunscreen, apply about 15 minutes before going out, and reapply every two hours and after swimming or sweating. This is general guidance, not product-specific validation."},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","text":"FDA: Sunscreen, how to help protect your skin from the sun","summary":"FDA guidance: use broad-spectrum SPF 15+, apply 15 minutes before sun exposure, reapply at least every two hours, and keep infants under 6 months out of the sun rather than using sunscreen."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0HBVTHQDG","text":"Amazon: kieró Prime Sun Gel reviews","summary":"4.5 out of 5 stars from 34 ratings (75% five-star; 5% two-star, none one-star) on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/sun-barrier","text":"kieroskincare.com: Prime Sun Gel SPF 40+ customer reviews","summary":"kieró''s own product page shows 310 reviews, 93% of them five stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-essential-boost-serum', 'Essential Boost Serum', 'kieró', 'skincare', 'physical', 'A lightweight serum with prickly pear, peptides, niacinamide and panthenol, plus several forms of hyaluronic acid. kieró positions it to hydrate, improve firmness, even out skin tone and strengthen the skin barrier for a brighter complexion. Apply a small amount to clean face and neck, morning and night. It is step 3 (treat) of kieró''s 5-step routine.', '$11.99 for 30 ml (1.01 fl oz)', '/products/catalog/p-kiero-essential-boost-serum.webp', 'https://us.kieroskincare.com/products/essential-boost-serum', '["skin","serum","niacinamide","hyaluronic acid","peptides","hydration","hyperpigmentation","vegan"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic serum; not an FDA-cleared drug or medical device. kieró states its products are vegan and cruelty-free; ayna did not independently verify that.","materials":"Water-based gel serum (30 ml / 1.01 fl oz). Key ingredients: panthenol, niacinamide, hydroxyethyl urea, beta-glucan, prickly pear (Opuntia ficus-indica) extract, centella compounds (madecassoside, asiaticoside), ten forms of hyaluronic acid, and two peptides (palmitoyl tetrapeptide-7, palmitoyl tripeptide-1). It also contains a protease enzyme, phenoxyethanol as a preservative, and mica, titanium dioxide and red iron oxide as colorants. kieró doesn''t list ingredient percentages. No added fragrance appears in the published ingredient list.","recalls":"No recalls found.","sideEffects":"None reported by kieró. As with any new skincare product, patch test first if you have sensitive skin, and stop using it if you get redness, burning or a rash. Full warnings are listed below.","opinionAlerts":"kieró doesn''t list the niacinamide percentage, and its firmness and tone claims are its own: no independent study of the finished product, its peptides, or its prickly pear extract was found."}'::jsonb, 'kieró says the serum hydrates and protects with antioxidants, improves firmness, evens out skin tone, and soothes and strengthens the skin barrier. No independent study of this product was found, so what follows is what the research says about its main ingredients.

Niacinamide has the best evidence. In two 12-week, double-blind, split-face trials, each with 50 women, 5% niacinamide improved fine lines and wrinkles, dark spots, red blotchiness, sallowness and elasticity compared with the same cream without it. Both trials were run by Procter & Gamble, and kieró doesn''t say how much niacinamide this serum contains.

For hydration, a randomized trial of 76 women found that 0.1% hyaluronic acid eye creams improved skin hydration and elasticity over 60 days compared with a placebo cream, and the lower-molecular-weight forms also reduced wrinkle depth. Panthenol''s active form, dexpanthenol, improved hydration and reduced water loss through the skin within 7 days in a small double-blind, placebo-controlled study.

No independent clinical trial of its two peptides (palmitoyl tetrapeptide-7 and palmitoyl tripeptide-1) or of prickly pear extract on skin was found, so the firmness claim rests on kieró.', 'kieró''s US site shows 236 customer reviews, and 213 of them (90%) are five stars; the rest are four stars. Most reviews are in Spanish and describe skin looking hydrated and smoother. For example: "Llevo casi un mes usándolo y mi piel se ve muy hidratada y bonita" ("I''ve been using it for almost a month and my skin looks very hydrated and pretty"). On Amazon it has 4.4 out of 5 stars from 37 ratings (69% five-star; 8% two-star, none one-star) as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Niacinamide improved wrinkles, dark spots and redness in controlled trials at 5%, and hyaluronic acid and panthenol have small controlled studies for hydration.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/essential-boost-serum"},"ingredients":"Full INCI list per kieró: Water, Butylene Glycol, Glycerin, Panthenol, Dipropylene Glycol, Niacinamide, Benzyl Glycol, Hydroxyethyl Urea, Carbomer, Arginine, Methylpropanediol, Beta-Glucan, Betaine, Ethylhexylglycerin, Protease, Hydrolyzed Sclerotium Gum, Caprylyl Glycol, Adenosine, Mica (CI 77019), 1,2-Hexanediol, Opuntia Ficus-Indica Fruit Extract, Agar, Gellan Gum, Calcium Alginate, Phenoxyethanol, Steareth-30, Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Dimethylsilanol Hyaluronate, Potassium Hyaluronate, Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Sodium Hyaluronate Dimethylsilanol, Sodium Acetylated Hyaluronate, Palmitoyl Tetrapeptide-7, Palmitoyl Tripeptide-1, Titanium Dioxide (CI 77891), Iron Oxides Red (CI 77491).","doctorOpinionShort":"Niacinamide improved wrinkles, dark spots and redness in two 12-week controlled trials at 5%, but kieró doesn''t list this serum''s percentage. Hyaluronic acid and panthenol have small controlled studies for hydration. No independent study of the product, its peptides, or its prickly pear extract was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/essential-boost-serum","label":"kieroskincare.com: Essential Boost Serum, ingredient list and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/16029679/","label":"PubMed: Niacinamide, a B vitamin that improves aging facial skin appearance","chipLabel":"Niacinamide trial, 50 women (2005)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18492135/","label":"PubMed: Topical niacinamide reduces yellowing, wrinkling, red blotchiness, and hyperpigmented spots in aging facial skin","chipLabel":"Niacinamide trial, 50 women (2004)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/22052267/","label":"PubMed: Efficacy of cream-based formulations of hyaluronic acid of different molecular weights in anti-wrinkle treatment","chipLabel":"Hyaluronic acid trial, 76 women (2011)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/10965426/","label":"PubMed: Effect of topically applied dexpanthenol on epidermal barrier function and stratum corneum hydration","chipLabel":"Dexpanthenol skin barrier trial (2000)"}],"whoItsFor":["People who want a lightweight hydrating serum for morning and night","People interested in niacinamide for uneven tone, dark spots or redness","People who prefer a fragrance-free, vegan formula"],"howToUse":{"intro":"Per kieró''s own site: use as step 3 (treat) of the routine, morning and night.","steps":["Cleanse your face first.","Apply a small amount to your face and neck.","Follow with moisturizer, and sunscreen in the morning."],"sourceUrl":"https://us.kieroskincare.com/products/essential-boost-serum","sourceLabel":"kieroskincare.com: Essential Boost Serum"},"warnings":["Sensitive skin: patch test first.","Keep out of eyes. If you get redness, burning, or a rash, stop using it."],"ingredientScience":[{"name":"Niacinamide","text":"kieró states this evens out skin tone. In two 12-week, double-blind, split-face trials of 50 women each, 5% niacinamide improved fine lines and wrinkles, dark spots, red blotchiness, sallowness and elasticity compared with the same cream without it, and was well tolerated. Both trials were run by Procter & Gamble. kieró doesn''t list this serum''s niacinamide percentage.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16029679/","label":"PubMed: Niacinamide, a B vitamin that improves aging facial skin appearance (Bissett et al., 2005)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18492135/","label":"PubMed: Topical niacinamide reduces yellowing, wrinkling, red blotchiness, and hyperpigmented spots in aging facial skin (Bissett et al., 2004)"}]},{"name":"Hyaluronic acid","text":"kieró states this hydrates. In a randomized trial of 76 women, eye creams with 0.1% hyaluronic acid applied twice daily for 60 days improved skin hydration and elasticity compared with a placebo cream on the other eye. Only the lower-molecular-weight forms also reduced wrinkle depth. This serum combines ten forms of hyaluronic acid at unlisted amounts.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22052267/","label":"PubMed: Efficacy of cream-based formulations of hyaluronic acid of different molecular weights in anti-wrinkle treatment (Pavicic et al., 2011)"}]},{"name":"Panthenol","text":"kieró states this soothes and strengthens the skin barrier. In a small randomized, double-blind, placebo-controlled study, dexpanthenol (panthenol''s active form) improved skin hydration and reduced water loss through the skin after 7 days compared with the same creams without it. A 2017 review describes its use as a moisturizer and barrier restorer; three of its four authors work for Bayer Consumer Care.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10965426/","label":"PubMed: Effect of topically applied dexpanthenol on epidermal barrier function and stratum corneum hydration (Gehring & Gloor, 2000)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28503966/","label":"PubMed: Topical use of dexpanthenol, a 70th anniversary article (Proksch et al., 2017)"}]},{"name":"Madecassoside (centella)","text":"No study testing madecassoside alone for barrier strength was found. In a 6-month double-blind study of 20 women, a cream combining 5% vitamin C with 0.1% madecassoside improved wrinkles, firmness, and hydration, but the result can''t be credited to madecassoside alone.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FRMCLFT1","text":"Amazon: kieró Essential Boost Serum reviews","summary":"4.4 out of 5 stars from 37 ratings (69% five-star; 8% two-star, none one-star) on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/essential-boost-serum","text":"kieroskincare.com: Essential Boost Serum customer reviews","summary":"kieró''s own product page shows 236 reviews, 90% of them five stars and the rest four stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-pure-radiant-eye-cream', 'Pure Radiant Eye Cream', 'kieró', 'skincare', 'physical', 'An eye cream with retinal, pink algae (Dunaliella salina), centella asiatica and niacinamide. kieró positions it to smooth fine lines, brighten dark circles and firm the eye area, in a lightweight formula that soothes delicate skin. Apply a small amount around the eyes once a day, preferably at night. It is step 3 (treat) of kieró''s 5-step routine.', '$12.99 for 25 ml (0.85 fl oz)', '/products/catalog/p-kiero-pure-radiant-eye-cream.webp', 'https://us.kieroskincare.com/products/pure-radiant-eye-cream', '["skin","eye cream","retinal","retinoid","niacinamide","dark circles","fine lines","vegan"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic eye cream; not an FDA-cleared drug or medical device. kieró states its products are vegan and cruelty-free; ayna did not independently verify that.","materials":"Cream (25 ml / 0.85 fl oz). Key ingredients: retinal (retinaldehyde, a retinoid), niacinamide, pink algae (Dunaliella salina) extract, centella compounds (madecassoside, asiaticoside), adenosine, a peptide (dipeptide diaminobutyroyl benzylamide diacetate), vitamin E, and macadamia, rosehip and olive oils, plus several botanical extracts. kieró doesn''t list the retinal or niacinamide percentage. No added fragrance appears in the published ingredient list.","recalls":"No recalls found.","sideEffects":"Contains a retinoid. A 2015 meta-analysis found no significant increase in birth defects or miscarriage after topical retinoid use in early pregnancy, but said the data aren''t strong enough to justify using retinoids while pregnant, so ask your clinician first if you''re pregnant, trying to conceive or breastfeeding. It also contains macadamia oil and many plant extracts, so patch test first if you have sensitive skin or nut or plant allergies. Full warnings are listed below.","opinionAlerts":"Contains retinal, a retinoid: ask your clinician before using it if you''re pregnant, trying to conceive or breastfeeding. kieró doesn''t list its retinal percentage."}'::jsonb, 'kieró says retinal smooths fine lines and wrinkles, the formula brightens dark circles, centella calms and strengthens the eye area, and niacinamide evens out tone. No independent study of this product was found, so what follows is what the research says about its main ingredients.

Retinal (retinaldehyde) is the natural precursor of retinoic acid, the prescription retinoid. In a 3-month randomized, double-blind trial of 40 Korean women, retinal creams at 0.1% and 0.05% applied twice daily improved texture around the crow''s feet and skin hydration, were well tolerated, and only the 0.1% cream improved pigmentation. The trial compared the two strengths and had no placebo group. kieró doesn''t list this cream''s retinal percentage.

Niacinamide improved fine lines, dark spots and redness in two 12-week controlled trials at 5%, run by Procter & Gamble; this cream''s percentage isn''t listed. For the pink algae, a placebo-controlled study of a Dunaliella salina extract reported fewer wrinkles and spots under intense sun exposure, but it was run by the company that sells that extract, and it may not be the same extract used here.

Retinoids and pregnancy: a 2015 meta-analysis of 654 pregnancies exposed to topical retinoids found no significant increase in birth defects or miscarriage, but its authors said the data aren''t strong enough to justify using topical retinoids during pregnancy.', 'kieró''s US site shows 325 customer reviews, and 291 of them (90%) are five stars; 33 are four stars and one is two stars. Most reviews are in Spanish, and several are from people who had only just started using it. One reviewer wrote that after less than a month: "aún no veo grandes cambios pero sí una mejora en la textura de la piel del contorno de mis ojos" ("I don''t see big changes yet, but I do see better texture in the skin around my eyes"). On Amazon it has 3.8 out of 5 stars from 55 ratings as of October 2026, noticeably lower than on kieró''s site. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s search listing.', 'Retinal improved skin texture and hydration around the crow''s feet in a small 3-month trial, and niacinamide improved fine lines and dark spots in controlled trials at 5%.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/pure-radiant-eye-cream"},"ingredients":"Full INCI list per kieró: Water, Caprylic/Capric Triglyceride, Glycerin, Butylene Glycol, Pentaerythrityl Tetraethylhexanoate, Polyglyceryl-3 Methylglucose Distearate, Niacinamide, Cetearyl Alcohol, Glyceryl Stearate SE, 1,2-Hexanediol, Cetearyl Olivate, Betaine, Hydroxyacetophenone, Sorbitan Olivate, Glyceryl Stearate, Carbomer, Arginine, Sodium Polyacrylate, Hydrogenated Polydecene, Retinal, Tocopherol, Centella Asiatica Extract, Adenosine, Disodium EDTA, Trideceth-6, Dunaliella Salina Extract, Macadamia Integrifolia Seed Oil, Rosa Canina Fruit Oil, Olea Europaea (Olive) Fruit Oil, Lactobacillus Ferment Lysate, C11-13 Isoparaffin, Bambusa Vulgaris Sap Extract, Caprylyl Glycol, Moringa Oleifera Seed Extract, Thuja Orientalis Leaf Extract, Zanthoxylum Piperitum Fruit Extract, Polygonum Cuspidatum Root Extract, Madecassoside, Dipeptide Diaminobutyroyl Benzylamide Diacetate, Asiaticoside, Ethylhexylglycerin, Asiatic Acid, Madecassic Acid, Centaurea Cyanus Flower Extract, Paeonia Albiflora Flower Extract, Nymphaea Caerulea Flower Extract, Sophora Japonica Flower Extract, Crocus Sativus Flower Extract, Histidine, Taurine, Ornithine, Phenylalanine, Proline, Aspartic Acid, Serine, Alanine, Isoleucine, Methionine, Valine, Leucine, Glycine, Glutamic Acid.","doctorOpinionShort":"Retinal improved skin texture and hydration in a small 3-month trial, and niacinamide has good controlled-trial evidence at 5%, but kieró doesn''t list either percentage. No independent study of this cream was found. It contains a retinoid, so ask your clinician first if you''re pregnant, trying to conceive or breastfeeding.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/pure-radiant-eye-cream","label":"kieroskincare.com: Pure Radiant Eye Cream, ingredient list and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/29663701/","label":"PubMed: Efficacy and safety of retinaldehyde 0.1% and 0.05% creams used to treat photoaged skin","chipLabel":"Retinal trial, 40 women (2018)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/16029679/","label":"PubMed: Niacinamide, a B vitamin that improves aging facial skin appearance","chipLabel":"Niacinamide trial, 50 women (2005)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18492135/","label":"PubMed: Topical niacinamide reduces yellowing, wrinkling, red blotchiness, and hyperpigmented spots in aging facial skin","chipLabel":"Niacinamide trial, 50 women (2004)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8879334/","label":"NIH (PMC): A Dunaliella salina extract counteracts skin aging under intense solar irradiation","chipLabel":"Pink algae extract study (2022)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26215715/","label":"PubMed: Pregnancy outcomes following first-trimester exposure to topical retinoids, systematic review and meta-analysis","chipLabel":"Retinoids in pregnancy meta-analysis (2015)"}],"whoItsFor":["People looking for a gentle retinoid eye cream for fine lines","People interested in niacinamide for dark circles or uneven tone around the eyes","Not for use during pregnancy or while trying to conceive without checking with a clinician first"],"howToUse":{"intro":"Per kieró''s own site: use once a day, preferably at night.","steps":["Apply a small amount to the eye contour area.","Massage gently until absorbed."],"sourceUrl":"https://us.kieroskincare.com/products/pure-radiant-eye-cream","sourceLabel":"kieroskincare.com: Pure Radiant Eye Cream"},"warnings":["Pregnant, trying to conceive, or breastfeeding: contains a retinoid (retinal), so ask your clinician first.","Nut or plant allergies (it contains macadamia oil and several plant extracts): patch test first.","Keep out of eyes. If you get redness, burning, or a rash, stop using it."],"ingredientScience":[{"name":"Retinal (retinaldehyde)","text":"kieró states this smooths fine lines and wrinkles. In a 3-month randomized, double-blind trial of 40 Korean women, 0.1% and 0.05% retinal creams applied twice daily improved texture around the crow''s feet (about 13%) and skin hydration, and were well tolerated; only the 0.1% cream improved pigmentation. The trial compared the two strengths and had no placebo group. kieró doesn''t list this cream''s retinal percentage.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29663701/","label":"PubMed: Efficacy and safety of retinaldehyde 0.1% and 0.05% creams used to treat photoaged skin (Kwon et al., 2018)"}]},{"name":"Topical retinoids in pregnancy","text":"A 2015 meta-analysis of 654 pregnant women exposed to topical retinoids in the first trimester, compared with 1,375 unexposed, found no significant increase in major birth defects, miscarriage, low birth weight or prematurity. Its authors said this can reassure people exposed by accident, but the data aren''t strong enough to justify using topical retinoids during pregnancy.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26215715/","label":"PubMed: Pregnancy outcomes following first-trimester exposure to topical retinoids, systematic review and meta-analysis (Kaplan et al., 2015)"}]},{"name":"Niacinamide","text":"kieró states this evens out skin tone. In two 12-week, double-blind, split-face trials of 50 women each, 5% niacinamide improved fine lines and wrinkles, dark spots, red blotchiness, sallowness and elasticity compared with the same cream without it. Both trials were run by Procter & Gamble and tested the whole face, not the eye area. kieró doesn''t list this cream''s niacinamide percentage.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16029679/","label":"PubMed: Niacinamide, a B vitamin that improves aging facial skin appearance (Bissett et al., 2005)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18492135/","label":"PubMed: Topical niacinamide reduces yellowing, wrinkling, red blotchiness, and hyperpigmented spots in aging facial skin (Bissett et al., 2004)"}]},{"name":"Pink algae (Dunaliella salina extract)","text":"In a placebo-controlled study under intense sun exposure, a Dunaliella salina extract rich in colorless carotenoids reduced skin glycation scores and improved wrinkle counts and spots compared with placebo. The authors work for the company that sells that extract, and it may not be the same extract kieró uses.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8879334/","label":"NIH (PMC): A Dunaliella salina extract counteracts skin aging under intense solar irradiation (Havas et al., 2022)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FRMQZRF3","text":"Amazon: kieró Pure Radiant Eye Cream reviews","summary":"3.8 out of 5 stars from 55 ratings on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/pure-radiant-eye-cream","text":"kieroskincare.com: Pure Radiant Eye Cream customer reviews","summary":"kieró''s own product page shows 325 reviews, 90% of them five stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-moisturizing-barrier-cream', 'Moisturizing Barrier Cream', 'kieró', 'skincare', 'physical', 'A face and neck cream with squalane, panthenol, several forms of hyaluronic acid, ceramide NP, and blue agave extract. kieró says it strengthens the skin barrier, prevents moisture loss, and hydrates dull skin without a greasy feel. It is step 4 (hydrate) of kieró''s 5-step routine, which blends Korean-beauty formulation with Latin American botanicals. Use morning and night.', '$12.99 for 50 g (1.76 oz) on kieró''s US site; $13.99 on Amazon', 'https://us.kieroskincare.com/cdn/shop/files/kiero_c1ec7bd0-990c-4bb7-a6f3-c6fd338869fe.jpg', 'https://us.kieroskincare.com/products/moisturizing-barrier-cream', '["skin","moisturizer","barrier","ceramides","squalane","hyaluronic acid","vegan","fragrance-free"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic moisturizer; not an FDA-approved drug. kieró states the formula is vegan and free of sulfates, parabens, and phthalates; ayna did not independently verify those claims.","materials":"Cream in a 50 g (1.76 oz) jar. The main moisturizing ingredients are squalane (second on the list), glycerin, panthenol, and eight forms of hyaluronic acid. Ceramide NP and the blue agave (Agave tequilana) leaf extract are near the end of the list, and kieró lists the agave at 1 ppm (0.0001%). No added fragrance or essential oils appear in the published ingredient list. Amazon lists the manufacturer as GreenCos Co., Ltd.","recalls":"No recalls found.","sideEffects":"kieró''s page lists no warnings. The Amazon listing advises stopping and seeing a specialist if redness or itching appears, not applying it to wounds or irritated skin, and rinsing right away if it gets in your eyes. Full warnings are listed below.","opinionAlerts":"Blue agave is the headline ingredient, but kieró''s own ingredient list gives it at 1 ppm (0.0001%), and ceramide NP is listed near the end, so it is likely present in a small amount. Benefit claims (barrier repair, less moisture loss) come from kieró, and no study of the finished product was found."}'::jsonb, 'kieró says this cream strengthens the skin barrier and prevents moisture loss, with blue agave for hydration, ceramides for the barrier, and squalane for a smooth finish. No independent study of this product was found, so what follows is what the research says about its main ingredients.

Ceramides are the best-studied barrier ingredient here. In a 12-week, double-blind study of people using a prescription acne gel (adapalene with benzoyl peroxide), those who also used a ceramide cleanser and lotion kept lower water loss through the skin and had less dryness than those using a basic face wash. That tested a different brand''s ceramide routine in people on irritating acne medicine. kieró lists ceramide NP near the end of its ingredient list and doesn''t give its amount.

The blue agave that kieró features is listed at 1 ppm, or 0.0001% of the formula. ayna found no study of agave leaf extract on skin.

The bulk of the hydration likely comes from ingredients higher on the list: squalane, glycerin, panthenol, and eight forms of hyaluronic acid. A review written by Bayer (which sells dexpanthenol creams) says studies support panthenol''s moisturizing and barrier benefits. A review co-written by L''Oréal scientists says many studies support topical hyaluronic acid for skin hydration. The American Academy of Dermatology lists hyaluronic acid and glycerin among the ingredients to look for in a moisturizer for dry skin and recommends fragrance-free products.', 'kieró''s US site shows 4.91 out of 5 from 213 reviews; its rating bars show 194 reviews (91%) in the top row and 19 (9%) in the second, with none lower. On Amazon it has 4.0 out of 5 stars from 54 ratings as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Moisturizes with squalane, glycerin, panthenol, and hyaluronic acid. Ceramides have good evidence for barrier repair, but ceramide NP is near the end of the list and the featured agave is at 1 ppm. No independent study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/moisturizing-barrier-cream","Amazon":"https://www.amazon.com/dp/B0FRMRCRBP"},"ingredients":"Full INCI list per kieró: Water, Squalane, Butylene Glycol, 1,2-Hexanediol, Panthenol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Allantoin, Ethylhexylglycerin, Dextrin, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Polyisobutene, Disodium EDTA, Gardenia Florida Fruit Extract, Sodium Hyaluronate, Caprylyl/Capryl Glucoside, Sorbitan Oleate, Glycerin, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Potassium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydrogenated Lecithin, Agave Tequilana Leaf Extract (1 ppm), Ceramide NP, Pentylene Glycol, Sodium Acetylated Hyaluronate.","doctorOpinionShort":"A fragrance-free cream built on squalane, glycerin, panthenol, and hyaluronic acid, ingredients the AAD recommends for dry skin. Ceramides have good evidence for barrier repair, but ceramide NP is near the end of the list here, and the featured blue agave is listed at just 1 ppm. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/moisturizing-barrier-cream","label":"kieroskincare.com: Moisturizing Barrier Cream, ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin","label":"American Academy of Dermatology: Dermatologists'' tips for relieving dry skin"}],"whoItsFor":["Normal, dry, or combination skin looking for a light daily moisturizer","People who prefer a fragrance-free, vegan formula","People using drying acne treatments who want a simple moisturizer (ceramide moisturizers helped in one study of a different brand)"],"howToUse":{"intro":"Per kieró''s own site: use morning and night as step 4 (hydrate) of the routine.","steps":["Cleanse and prepare your skin first.","Spread an even amount over your face and neck.","Use morning and night to seal in moisture. The AAD suggests applying moisturizer while skin is still damp."],"sourceUrl":"https://us.kieroskincare.com/products/moisturizing-barrier-cream","sourceLabel":"kieroskincare.com: Moisturizing Barrier Cream"},"warnings":["Redness or itching after use: stop and see a doctor (per the Amazon listing).","Don''t apply to wounds or irritated skin (per the Amazon listing).","Keep out of eyes; if it gets in, rinse right away (per the Amazon listing)."],"ingredientScience":[{"name":"Ceramide NP","text":"kieró states ceramides help maintain the skin barrier. In a 12-week, double-blind study, people using a prescription acne gel (adapalene 0.3% with benzoyl peroxide 2.5%) who also used a ceramide-containing cleanser and lotion had lower water loss through the skin and less dryness, redness, and scaling than those using a basic face wash. That study tested a different brand''s ceramide routine. kieró lists ceramide NP second to last and doesn''t give its amount.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/37276158/","label":"PubMed: Ceramide-containing adjunctive skin care for skin barrier restoration during acne vulgaris treatment (2023)"}]},{"name":"Panthenol (provitamin B5)","text":"Fifth on the ingredient list. A review written with Bayer, which makes dexpanthenol creams, says various studies confirm its moisturizing and barrier-supporting effects. kieró doesn''t list its concentration.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28503966/","label":"PubMed: Topical use of dexpanthenol, a 70th anniversary article (2017)"}]},{"name":"Hyaluronic acid (eight forms)","text":"kieró''s formula contains eight forms of hyaluronic acid and its salts. A review co-written by L''Oréal scientists says many studies support topical hyaluronic acid for skin hydration. The American Academy of Dermatology lists hyaluronic acid and glycerin among the ingredients to look for in a moisturizer for dry skin.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36200921/","label":"PubMed: Benefits of topical hyaluronic acid for skin quality and signs of skin aging (2022)"},{"url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin","label":"American Academy of Dermatology: Dermatologists'' tips for relieving dry skin"}]},{"name":"Blue agave (Agave tequilana) leaf extract","text":"kieró features blue agave for lasting hydration, but its ingredient list gives the extract at 1 ppm (0.0001% of the formula). ayna found no study of agave leaf extract on skin.","citations":[{"url":"https://us.kieroskincare.com/products/moisturizing-barrier-cream","label":"kieroskincare.com: Moisturizing Barrier Cream ingredient list"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin","text":"American Academy of Dermatology: Dermatologists'' tips for relieving dry skin","summary":"AAD guidance: choose a fragrance-free cream or ointment, look for ingredients such as hyaluronic acid and glycerin, and apply while skin is still damp. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FRMRCRBP","text":"Amazon: kieró Moisturizing Barrier Cream reviews","summary":"4.0 out of 5 stars from 54 ratings on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/moisturizing-barrier-cream","text":"kieroskincare.com: Moisturizing Barrier Cream customer reviews","summary":"kieró''s own product page shows 4.91 out of 5 from 213 reviews."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-balance-toner-pads', 'Balance Toner Pads', 'kieró', 'skincare', 'physical', 'Pre-soaked toner pads with glycolic acid (an AHA), gluconolactone (a PHA), passion fruit extract, panthenol, and hyaluronic acid. kieró says they gently exfoliate, renew skin texture, fade dark spots, minimize the look of pores, and hydrate. It is step 2 (balance) of kieró''s 5-step routine. Wipe over the face after cleansing, avoiding the eyes. Because it contains an AHA, the FDA advises daily sunscreen while using it.', '$12.99 for 60 pads (185 ml / 6.26 fl oz) on kieró''s US site; $13.99 on Amazon', 'https://us.kieroskincare.com/cdn/shop/files/kiero-_-_-05.jpg', 'https://us.kieroskincare.com/products/balance-toner-pads', '["skin","toner","exfoliation","aha","pha","glycolic acid","vegan","fragrance-free"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic toner; not an FDA-approved drug. kieró doesn''t publish the glycolic acid percentage or the product''s pH. kieró states the formula is vegan and free of sulfates, parabens, and phthalates; ayna did not independently verify those claims.","materials":"60 cotton pads in 185 ml (6.26 fl oz) of toner. Exfoliating acids: glycolic acid (AHA) and gluconolactone (PHA), with potassium hydroxide to adjust pH. The second ingredient is tea tree leaf water (a water distilled from the leaves, not tea tree oil). Also contains glycerin, allantoin, panthenol, hyaluronic acid, passion fruit extract, and cyanocobalamin (vitamin B12, which is pink). No added fragrance appears in the published ingredient list. Amazon lists the manufacturer as Natuzen Co., Ltd.","recalls":"No recalls found.","sideEffects":"Glycolic acid makes skin more sensitive to the sun. In a study the FDA cites, 4 weeks of 10% glycolic acid increased sunburn cells and lowered the UV dose needed to redden skin; the effect was gone a week after stopping. The FDA recommends AHA products carry a sunburn alert telling users to wear sunscreen; kieró''s page and the Amazon listing don''t include one. The AAD warns that exfoliating while using retinoids or benzoyl peroxide can worsen dryness. Full warnings are listed below.","opinionAlerts":"Sun sensitivity: contains glycolic acid, so use sunscreen daily while using these and for a week after stopping (FDA). kieró doesn''t give the acid strength or pH. Benefit claims (fading dark spots, smaller-looking pores, oil control) come from kieró, and no study of the finished product was found."}'::jsonb, 'kieró says these pads gently exfoliate with AHA and PHA, renew texture, fade dark spots, minimize the look of pores, and hydrate, and that passion fruit extract helps control excess oil. No independent study of this product was found, so what follows is what the research and regulators say about its main ingredients.

Glycolic acid is the most common alpha hydroxy acid (AHA). The FDA says AHAs make skin more sensitive to the sun: in a study of 29 people that the FDA cites, applying 10% glycolic acid for 4 weeks increased sunburn cells and lowered the amount of UV needed to redden the skin. The effect went away within a week of stopping. The FDA recommends AHA products carry a "Sunburn Alert" and that users wear sunscreen during use and for a week after. kieró''s page doesn''t include this alert, and it doesn''t say how much glycolic acid the pads contain or what their pH is. The FDA notes that an expert safety panel considers glycolic acid products safe at 10% or less with a pH of 3.5 or higher, when they protect against sun sensitivity or tell users to use sun protection daily.

Gluconolactone is a polyhydroxy acid (PHA). In lab tests it gave some protection against UV damage, and in a small human test it did not significantly increase sunburn cells, but the authors said more research is needed.

The second ingredient is tea tree leaf water, which is different from tea tree oil. A safety review of tea tree oil says topical use is relatively safe and adverse events are minor, but some people are allergic to it. ayna found no study of the leaf water or of the passion fruit extract on skin.

The American Academy of Dermatology says people with sensitive, dry, or acne-prone skin may do best with a mild chemical exfoliant, should moisturize right after, and shouldn''t exfoliate on broken or sunburned skin or while using retinoids or benzoyl peroxide.', 'kieró''s US site shows 4.92 out of 5 from 420 reviews; its rating bars show 391 reviews (93%) in the top row, 26 (6%) in the second, 2 in the third, none in the fourth, and 1 in the lowest. On Amazon it has 4.3 out of 5 stars from 56 ratings as of October 2026. The first set of reviews is on kieró''s own site; the Amazon rating is from Amazon''s product page.', 'Glycolic acid and gluconolactone exfoliate chemically; the strength isn''t disclosed. Claims about dark spots, pores, and oil control come from kieró. No independent study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/balance-toner-pads","Amazon":"https://www.amazon.com/dp/B0FRM64YB5"},"ingredients":"Full INCI list per kieró: Water, Melaleuca Alternifolia (Tea Tree) Leaf Water, Butylene Glycol, 1,2-Hexanediol, Glycerin, Glycolic Acid, Potassium Hydroxide, Allantoin, Gluconolactone, Panthenol, Sodium Hyaluronate, Cyanocobalamin, Passiflora Edulis Fruit Extract, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Pentylene Glycol, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate.","doctorOpinionShort":"Toner pads with glycolic acid (an AHA) and gluconolactone (a PHA) for gentle chemical exfoliation. kieró doesn''t say how strong the acid is, and AHAs make skin more sun-sensitive, so the FDA advises daily sunscreen while using them and for a week after. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/balance-toner-pads","label":"kieroskincare.com: Balance Toner Pads, ingredient list and claims"},{"url":"https://www.fda.gov/cosmetics/cosmetic-ingredients/alpha-hydroxy-acids","label":"FDA: Alpha hydroxy acids in cosmetics"},{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","label":"American Academy of Dermatology: How to safely exfoliate at home"}],"whoItsFor":["People who want gentle chemical exfoliation in a quick wipe-on step","Normal, oily, or combination skin looking to smooth rough texture","People who already wear sunscreen every day (needed with any AHA product)"],"howToUse":{"intro":"Per kieró''s own site and the Amazon listing: use daily, morning or night, as step 2 (balance) of the routine.","steps":["Cleanse your skin first.","Gently wipe one pad over your face and neck, avoiding the eye area.","Follow with serum and moisturizer. The AAD recommends moisturizing right after exfoliating.","Wear sunscreen every day while using these and for a week after you stop. The FDA recommends this for any AHA product."],"sourceUrl":"https://us.kieroskincare.com/products/balance-toner-pads","sourceLabel":"kieroskincare.com: Balance Toner Pads"},"warnings":["Sun sensitivity: contains glycolic acid (an AHA). Use sunscreen, cover up, and limit sun exposure while using it and for a week after (FDA).","Using a prescription retinoid, retinol, or benzoyl peroxide: exfoliating on top of them can worsen dryness and irritation (AAD).","Don''t use on broken, cut, or sunburned skin (AAD).","Contains tea tree leaf water. Some people are allergic to tea tree; stop if you get redness or itching.","Keep out of eyes; if it gets in, rinse right away (per the Amazon listing)."],"ingredientScience":[{"name":"Glycolic acid (AHA)","text":"kieró states AHA refines texture and unclogs pores. In a randomized, double-blind study of 29 people, cited by the FDA, 10% glycolic acid applied for 4 weeks increased sunburn cells and lowered the UV dose needed to redden the skin; the effect was gone a week after stopping. The FDA recommends AHA products carry a sunburn alert and notes that an expert panel considers glycolic acid products safe at 10% or less with a pH of 3.5 or higher, with daily sun protection. kieró doesn''t list the concentration or pH.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12713551/","label":"PubMed: Topical glycolic acid enhances photodamage by ultraviolet light (2003)"},{"url":"https://www.fda.gov/cosmetics/cosmetic-ingredients/alpha-hydroxy-acids","label":"FDA: Alpha hydroxy acids in cosmetics"}]},{"name":"Gluconolactone (PHA)","text":"kieró states PHA gently exfoliates. In a lab model, gluconolactone gave up to 50% protection against UV damage, and in a small human test it did not significantly increase sunburn cells. The authors said more research is needed. This was not a test of exfoliation or of this product.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/14756648/","label":"PubMed: The polyhydroxy acid gluconolactone protects against ultraviolet radiation in an in vitro model of cutaneous photoaging (2004)"}]},{"name":"Tea tree (Melaleuca alternifolia) leaf water","text":"The second ingredient. It is a water distilled from tea tree leaves, not the essential oil. A safety review of tea tree oil found topical use relatively safe, with minor and occasional side effects, but allergic reactions occur in some people. ayna found no study of the leaf water itself.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16243420/","label":"PubMed: A review of the toxicity of Melaleuca alternifolia (tea tree) oil (2006)"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","text":"American Academy of Dermatology: How to safely exfoliate at home","summary":"AAD guidance: people with dry, sensitive, or acne-prone skin should choose gentle exfoliation, moisturize afterward, and avoid exfoliating on broken or sunburned skin or while using retinoids or benzoyl peroxide. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FRM64YB5","text":"Amazon: kieró Balance Toner Pads reviews","summary":"4.3 out of 5 stars from 56 ratings on Amazon as of October 2026."},{"platform":"website","url":"https://us.kieroskincare.com/products/balance-toner-pads","text":"kieroskincare.com: Balance Toner Pads customer reviews","summary":"kieró''s own product page shows 4.92 out of 5 from 420 reviews."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
